use kynex_core::{Core,write_json};use serde_json::json;use std::sync::Arc;use std::time::Instant;
#[tokio::main]async fn main(){
 let t=tempfile::tempdir().unwrap();let mut c=Core::new(t.path().into(),Arc::new(|_|{})).unwrap();let dir=c.instance("qa").unwrap();
 write_json(&dir.join("kxl.json"),&json!({"id":"qa","name":"QA","version":"1.20.1","loader":"forge","settings":{"isolation":"all"}})).unwrap();
 let files=c.dispatch("project_versions",json!({"id":"qa","kind":"mods","source":"curseforge","project":238222,"game":"1.20.1","loader":"forge","paged":true})).await.unwrap();let old=files["versions"].as_array().unwrap().last().unwrap();let original=dir.join("mods/manually-renamed.jar");
 c.dispatch("download_resource_file",json!({"source":"curseforge","project":238222,"kind":"mods","versionId":old["id"],"path":original})).await.unwrap();assert!(!dir.join("installed-projects.json").exists());
 let start=Instant::now();let rows=c.dispatch("check_mod_updates",json!({"id":"qa","force":true})).await.unwrap();let row=&rows[0];println!("Manual import: {}",row);println!("Initial dual-source check: {:.2}s",start.elapsed().as_secs_f64());assert_eq!(row["status"],"update");assert!(row["identifiedSources"].as_array().unwrap().iter().any(|x|x=="curseforge"));
 let start=Instant::now();let cached=c.dispatch("check_mod_updates",json!({"id":"qa"})).await.unwrap();assert_eq!(cached[0]["cached"],true);println!("Cached check: {:.4}s",start.elapsed().as_secs_f64());
 std::fs::rename(&original,dir.join("mods/another-name.jar")).unwrap();let renamed=c.dispatch("check_mod_updates",json!({"id":"qa"})).await.unwrap();assert_eq!(renamed[0]["file"],"another-name.jar");assert_eq!(renamed[0]["cached"],true);
 std::fs::copy(dir.join("mods/another-name.jar"),dir.join("mods/duplicate.jar")).unwrap();let duplicates=c.dispatch("check_mod_updates",json!({"id":"qa"})).await.unwrap();assert!(duplicates.as_array().unwrap().iter().all(|r|r["status"]=="unknown"));std::fs::remove_file(dir.join("mods/duplicate.jar")).unwrap();println!("Duplicate enabled project files remain unconfirmed and do not offer replacement");
 let done=c.dispatch("update_mods",json!({"id":"qa","files":["another-name.jar"]})).await.unwrap();assert_eq!(done["updated"],1);assert!(dir.join("mods/another-name.jar.disabled").exists());println!("Manual file updated after fresh check; old renamed file backed up and disabled");
 let rows=c.dispatch("check_mod_updates",json!({"id":"qa","force":true})).await.unwrap();assert!(rows.as_array().unwrap().iter().all(|r|r["status"]=="current"));println!("Updated files confirmed current");
 c.http=reqwest::Client::builder().proxy(reqwest::Proxy::all("http://127.0.0.1:9").unwrap()).connect_timeout(std::time::Duration::from_secs(1)).build().unwrap();let failed=c.dispatch("check_mod_updates",json!({"id":"qa","force":true})).await.unwrap();assert!(failed.as_array().unwrap().iter().all(|r|r["status"]=="error"));println!("Forced network failure stays unconfirmed, never current");assert!(c.dispatch("update_mods",json!({"id":"qa"})).await.is_err());println!("Automatic update pauses when fresh detection fails");
}
